import{_ as t,o as s,c as n,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const m=JSON.parse('{"title":"OmniWorld: A Multi-Domain and Multi-Modal Dataset for 4D World Modeling","description":"","frontmatter":{"title":"OmniWorld: A Multi-Domain and Multi-Modal Dataset for 4D World Modeling","arxiv":"2509.12201","date":"2025-09-15","authors":"Yang Zhou, Yifan Wang, Jianjun Zhou, Wenzheng Chang, Haoyu Guo, Zizun Li, Kaijing Ma, Xinyue Li, et al.","categories":"cs.CV","topics":"4D世界建模, 多模态数据集, 相机可控视频生成","outline":[2,2]},"headers":[],"relativePath":"papers/2509.12201.md","filePath":"papers/2509.12201.md","lastUpdated":null}'),e={name:"papers/2509.12201.md"};function o(l,a,i,p,d,h){return s(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="omniworld-a-multi-domain-and-multi-modal-dataset-for-4d-world-modeling" tabindex="-1">OmniWorld: A Multi-Domain and Multi-Modal Dataset for 4D World Modeling <a class="header-anchor" href="#omniworld-a-multi-domain-and-multi-modal-dataset-for-4d-world-modeling" aria-label="Permalink to &quot;OmniWorld: A Multi-Domain and Multi-Modal Dataset for 4D World Modeling&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.12201" target="_blank" rel="noreferrer">2509.12201</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-15</td></tr><tr><td><strong>作者</strong></td><td>Yang Zhou, Yifan Wang, Jianjun Zhou, Wenzheng Chang, Haoyu Guo, Zizun Li, Kaijing Ma, Xinyue Li, et al.（Shanghai AI Lab 等）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 ReShade 从游戏渲染管线里直接取真值深度，配一套「前景掩码引导的两阶段动态相机位姿标注」流水线，把仿真、机器人、人类、互联网四域数据统一补齐五种模态，同时当 benchmark 和训练资源用。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>4D 世界建模要同时抓空间几何与时间动态。支撑它的两类基础任务——3D 几何基础模型（从 2D 图像恢复几何）与相机可控视频生成——都严重依赖带几何标注的大规模数据，而现有数据在两个方向上都不够。</p><p>评测这一侧的问题最直接：Sintel 平均只有 50 帧，长序列鲁棒性根本测不出来；Bonn 只有室内人体运动，KITTI 只有室外街景，运动幅度小、类型单一；相机可控生成这边，RealEstate10K 几乎全是静态场景加平滑运镜，与真实使用场景差距明显。训练这一侧同样：视频-文本数据规模大但缺深度、位姿、光流这些几何模态；有几何标注的合成数据集规模又太小。</p><p>论文的立场是：这不是模型问题，是数据问题，且评测与训练的缺口是同一个缺口。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>静态 3D 数据集</strong>（ScanNet、NYU-v2、MegaDepth）几何精确，但静态，无法建模运动与交互。<strong>视频-文本数据集</strong>（Panda-70M、OpenVid-1M、MiraData）语义标注丰富，缺几何模态。<strong>动态真实数据集</strong>（KITTI、Waymo、Bonn、HOI4D、RH20T、EPIC-Kitchens）有动态但场景多样性有限，且几何标注常常稀疏或含噪。<strong>合成数据集</strong>中，MPI Sintel 是光流研究的奠基工作但序列过短，FlyingThings++、TartanAir、Dynamic Replica、Spring 在规模、多样性与模态丰富度上都不及本文自采的 OmniWorld-Game。</p><p>为什么之前没人把这些补齐？关键的技术障碍在动态视频的相机位姿标注：转场、弱纹理区域、剧烈运动会让传统 SfM 失效，而动态前景本身就是干扰项。没有可靠的自动位姿标注，多域大规模数据就只能停留在「有 RGB 没几何」的状态。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一个线索来自图形学社区的老经验：Playing for Data 早就证明可以从游戏里拿真值。现代游戏渲染管线里深度缓冲是现成的，ReShade 能在渲染过程中挂钩取到，OBS 同步录屏拿 RGB——真值深度问题瞬间解决，而且现代游戏的场景多样性（荒野到城市、白天到黑夜、古代到科幻）远超任何手工搭建的合成环境。</p><p>第二个线索来自「哪些像素可以信任」这个判断。SfM 之所以在动态视频上失效，是因为它把运动前景当成静态结构去解算。但如果先有可靠的前景掩码，就可以只在静态背景上做匹配与光束法平差。而前景掩码恰好是当下开放词表分割模型（Grounding DINO + SAM、SAM 2）能自动产出的东西。两个模态之间形成了依赖链：掩码 → 位姿。</p><p>第三个判断是关于数据集角色的：既然自采数据比现有 benchmark 更长、更动态、更高清，那它天然既是更难的评测集，又是更有用的训练集。论文因此把「揭示 SOTA 的不足」与「微调后显著提升」放在一起论证——两者互为佐证。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>高质量 4D 标注的瓶颈在相机位姿，而位姿之所以难标是因为动态前景污染了几何约束。先把前景掩掉，再在纯静态区域上做「粗估 + 稠密点跟踪细化 + 光束法平差」，位姿就可以自动化地标到可用精度。有了位姿，深度、光流、caption 都可以各自用专用模型补齐，一个多域数据集就被统一到同一套模态规格上。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据获取</strong>分四域：</p><ul><li><strong>仿真域</strong>：自采的 OmniWorld-Game，用 ReShade 在渲染过程中取深度、OBS 同步录 RGB。96K 段片段、超过 1,851 万帧、总时长 214 小时以上、1280×720、24 FPS。</li><li><strong>机器人域</strong>：AgiBot、DROID、RH20T。</li><li><strong>人类域</strong>：RH20T-Human、HOI4D、Epic-Kitchens、Ego-Exo4D、HoloAssist、Assembly101、EgoDex，覆盖第一与第三人称。</li><li><strong>互联网域</strong>：CityWalk，提供真实街景，重点补相机位姿标注。</li></ul><p>合计 12 个异构数据集、超过 60 万段序列、3 亿帧以上，过半数据分辨率在 720P 及以上。</p><p><strong>预处理</strong>：视频切片过滤，剔除运动模糊、特征点不足、动态区域过大的帧，并把长视频切成可管理的短片段。</p><p><strong>标注流水线</strong>（以一段游戏第一人称探索视频为例）：</p><ol><li><strong>深度</strong>：游戏数据直接取渲染真值；AgiBot、HOI4D 的含噪稀疏深度用 Prior Depth Anything 优化成稠密深度；DROID 的双目数据用 FoundationStereo 估计。</li><li><strong>前景掩码</strong>：机器人域用 RoboEngine 产关键帧初始掩码，再用 SAM 2 做时序跟踪与融合；游戏域用 Grounding DINO 在预定义区域检测初始框，作为 SAM 的提示。</li><li><strong>相机位姿</strong>（两阶段）：粗估阶段，无深度时用 VGGT，有深度时用带深度约束的 DroidCalib；细化阶段，在掩码给出的静态区域上用 SIFT/SuperPoint 配合 CoTracker3 做稠密点跟踪，再做光束法平差最小化重投影误差，必要时用深度做前后向重投影增强。</li><li><strong>文本 caption</strong>：Qwen2-VL-72B-Instruct，按 81 帧分段；机器人与人类域先标整段任务再分段标注；游戏域按视角设计不同 prompt，产出短描述、玩家角色描述、背景描述、相机描述、视频描述与关键标签。每条 caption 主要落在 150–250 token 区间，标注密度高于 OpenVid-1M、Panda-70M 等。</li><li><strong>光流</strong>：DPFlow，能在原分辨率上直接预测，不像 RAFT 那样需要下采样，从而保留细微运动。</li></ol><p><strong>伦理处理</strong>：严格遵守游戏内容的使用条款（如 Rockstar Games 的规定），仅用于非商业用途，避免剧情剧透；用 ReShade 插件自动移除 UI 与文字，并人工筛除敏感场景。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文以数据构建与实证评测为主，没有提出新的形式化理论。位姿细化阶段用的是经典光束法平差：在静态区域上最小化跟踪点的重投影误差，求解相机外参（及可选的内参）。评测指标沿用标准定义——深度用绝对相对误差 Abs Rel 与阈值准确率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.25</span></span></span></span>，位姿用 ATE 与相对位姿误差 RPE，相对位姿评测用 AUC@5/10/20，生成质量用 FVD 与相机参数误差（TransErr、RotErr、CamMC）。</p><p>值得说明的是深度评测的两种对齐设置。scale-only 对齐只允许一个全局尺度因子，scale &amp; shift 额外允许一个平移偏置。后者更宽松，因此同一模型在 scale &amp; shift 下的 Abs Rel 明显更低（例如 VGGT 从 0.440 降到 0.194）。区分这两种设置的意义在于：如果一个模型只在 scale &amp; shift 下表现好，说明它的深度在序列内部相对正确但存在系统性偏置，这对下游的几何一致性是有影响的。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>现有几何基础模型在长序列高动态数据上还行吗？</strong> 在 OmniWorld-Game benchmark（最长 16 秒 / 384 帧、720P）上评测 DUSt3R、MASt3R、MonST3R、Fast3R、CUT3R、FLARE、VGGT、MoGe-1/2，图像统一缩放到长边 512。单目深度上 MoGe-2 最好（Abs Rel 0.401，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.25</span></span></span></span> 为 0.589），但离可用还很远；视频深度上 VGGT 在两种对齐下都最优（0.440 / 0.625 与 0.194 / 0.755），且 FPS 18.75 远高于竞争者；MASt3R 指标接近（0.482 / 0.579 与 0.217 / 0.724）但因全局对齐只有 0.79 FPS，实用性受限。结论是没有任何一个模型在所有指标上领先。（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span></span></span></span> 因基准数据已进入其训练集而未被评测，这是一个值得称道的严谨处理。）</p><p><strong>相机可控视频生成模型呢？</strong> 评测 AC3D（T2V）与 CamCtrl、MotionCtrl、CAMI2V（I2V）。CamCtrl 在相机精度与画质上均最好（TransErr 1.2882、RotErr 0.2022、CamMC 1.3856、FVD 615.417 / 637.574），AC3D 的 FVD 高达 1745.778 / 1594.885。定性上 AC3D 虽语义连贯但人物几乎不动且不遵循相机轨迹；CamCtrl 轨迹跟得住但运动主体模糊。</p><p><strong>微调后能提升多少？</strong> 几何侧：DUSt3R 微调后单目深度在 Sintel 从 0.488 / 0.532 提升到 0.370 / 0.529、Bonn 从 0.139 / 0.831 到 0.067 / 0.948，甚至超过在多个动态数据集上微调过的 MonST3R（0.402 / 0.525）；视频深度上 CUT3R 在 scale &amp; shift 设置的 Sintel 从 0.537 / 0.556 提升到 0.314 / 0.574；位姿上 CUT3R 的 Sintel ATE 从 0.210 降到 0.178，Reloc3r 在 DynPose-100K 的 AUC@5 从 6.9 提到 14.4、在 OmniWorld-CityWalk 从 33.3 提到 42.5。生成侧：AC3D 微调后在 OmniWorld-Game 上 TransErr 从 6.2788 降到 4.1428、FVD 从 1745.778 降到 1437.247；在<strong>未参与微调分布的 RealEstate10K</strong> 上也从 3.4433 / 479.320 改善到 2.8648 / 472.683，这一点比同分布提升更有说服力。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：4D 世界建模的瓶颈是同时具备规模、动态复杂度与几何标注的数据；从游戏渲染管线取真值深度是绕开真实世界深度采集困难的可行路径，并自带极高的场景多样性；动态视频的相机位姿可以自动标注，关键是先用分割模型掩掉前景再在静态区域上做跟踪与光束法平差；用统一流水线把 12 个异构数据集补齐到同一套五模态规格，使多域数据首次可以混合训练；该数据同时充当更难的 benchmark（暴露 SOTA 在长序列高动态下的不足）与有效的训练资源（微调后在公开基准上普遍提升）。</p><p><strong>3 句版</strong>：掩码 → 位姿 → 多模态补齐，是把已有数据集「升级」为 4D 训练资源的通用配方。现有几何基础模型在 384 帧、高动态、720P 的条件下没有一个全面领先。微调收益在跨分布的 RealEstate10K 上同样成立，说明提升不是过拟合到自采分布。</p><p><strong>1 句版</strong>：用游戏渲染缓冲拿真值、用前景掩码救活 SfM，把 4D 世界建模的数据瓶颈系统性地补上一块。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>自动标注流水线产出的几何标注足够准确，可以当作训练与评测的真值</strong>。整篇论文的两个核心论断都建立在它之上——benchmark 上 SOTA 表现不佳说明模型不足（而不是标注不准），微调后性能提升说明数据有价值（而不是模型在拟合标注器的偏差）。如果标注本身有系统性误差，两个论断同时动摇。</p><p>风险最集中的地方是相机位姿。粗估阶段用的是 VGGT 或 DroidCalib，二者本身就是被评测的同类模型或其近亲；细化虽然引入了独立的点跟踪与光束法平差，但初值来自这些模型。这带来一个循环风险：在自动标注的位姿上微调几何模型，可能只是让模型更接近标注器，而非更接近物理真值。论文提供的最强反驳证据是跨分布迁移——Reloc3r 微调后在 DynPose-100K 上 AUC@5 从 6.9 翻到 14.4，AC3D 微调后在 RealEstate10K 上也变好。这两个数据集的真值与本文流水线无关，因此提升难以用「拟合标注器」解释。但论文没有报告标注位姿自身的精度评估（例如在有真值的 TartanAir 或 ScanNet 上跑同一套流水线并给出误差分布），这是最直接却缺失的证据。</p><p>游戏深度这一路相对稳固——ReShade 取的是渲染管线的真值缓冲，误差来源主要是投影参数与后处理效果（景深、体积雾）造成的失配，论文未讨论这一点。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证，目标是直接检验标注流水线的精度，而不必复现整套数据集：</p><ul><li>数据：取一个自带真值位姿与深度的动态数据集（TartanAir 或 Dynamic Replica），选 20 条序列、每条 200 帧。</li><li>实现：在这些序列的 RGB 上完整跑一遍论文流水线——Grounding DINO/SAM 出前景掩码、VGGT 粗估位姿、CoTracker3 在静态区域跟踪、光束法平差细化。</li><li>测量：把流水线输出的位姿与真值比 ATE / RPE，深度比 Abs Rel；并做一个消融——去掉前景掩码（在全图上跟踪），看误差变化。</li><li>判据：若带掩码流水线的 ATE 与真值差距处于下游模型误差的一个量级以下，则「自动标注可当真值」成立；若两者同量级，则 benchmark 上的模型排序可能部分反映的是标注噪声。掩码消融同时能量化论文核心设计（掩掉前景）的实际贡献——这个数字论文本身没有给出。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释</strong>：微调带来的提升可能主要来自<strong>数据量与分辨率的增加</strong>，而非 OmniWorld 特有的多域多模态设计。DUSt3R 与 CUT3R 微调时都混入了各自的原始训练集，且训练超参（学习率、迭代数、分辨率设置）与原始预训练不同；一个更朴素的解释是「再训一轮 + 见到更多高分辨率动态数据」就够了。要证伪，可以设置一个对照：用同等帧数、同等分辨率的现有动态数据（TartanAir + Waymo 混合）做同样时长的微调，看能否复现类似增益。若能，则 OmniWorld 的独特价值需要重新界定为「规模」而非「多域多模态」。</p><p><strong>可预测的失败条件</strong>：动态区域占比过大的场景。整个位姿标注依赖「画面里有足够的静态背景可供匹配」，而预处理阶段已经明确剔除了动态区域过大的帧。这意味着数据集在构造上就系统性地排除了近距离交互、大范围遮挡、密集人群这类样本——而这些恰恰是 4D 世界建模最需要学的困难情形。反对者可以据此论证：在 OmniWorld 上训练与评测的模型，可能在最难的动态场景上仍然是盲的，而 benchmark 因为同样的筛选标准，无法暴露这个盲区。构造反例只需收集一批高动态占比视频（体育对抗、人群穿行）做定性测试。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：当前流水线把五种模态当作彼此独立的标注任务，各用一个专用模型产出，模态之间只在使用时被拼在一起。这带来两个后果：模态之间可能互相矛盾（估计的深度与解算的位姿在几何上不自洽，光流与深度暗示的运动不一致），而且没有任何机制去发现和消解这些矛盾。数据集因此有「精度上限」，但没有「置信度」。</p><p><strong>新的 framing</strong>：把多模态标注从「并行标注」重构为「<strong>联合一致性优化 + 逐像素置信度估计</strong>」——把深度、位姿、光流、掩码放进一个统一的几何自洽目标里联合优化（深度与位姿要能解释光流，光流的残差要在静态区域接近零），并输出每个标注的不确定度。这样数据集提供的不再只是标注，而是「标注 + 可信度」，下游训练可以据此加权，评测也可以只在高置信区域上算分。</p><p><strong>可借鉴的相邻领域工具</strong>：SLAM 里的因子图与联合优化天然处理这种多传感器一致性问题；自监督深度估计中的「光度重建损失 + 遮挡感知掩码」已经把深度、位姿、光流耦合在一起；概率标定与不确定度估计提供了现成的置信度输出方式。</p><p><strong>第一个实验</strong>：在 OmniWorld-Game 的一个子集上（有渲染真值深度可作校验）实现联合优化版流水线，输出带置信度的位姿与深度。度量三件事：(a) 联合优化后的位姿在有真值的合成子集上误差是否下降；(b) 置信度是否与实际误差相关（可靠性图）；(c) 在训练几何模型时按置信度加权采样，是否比均匀采样得到更好的下游性能。若三项都成立，那么「数据集应当提供不确定度」就会从一个工程细节升级为多域数据集构建的默认要求。</p>',50)])])}const c=t(e,[["render",o]]);export{m as __pageData,c as default};
